#include <cstdint>
#include <iostream>
#include <limits>

// Meant to say whether pos + qty overflows. It relies on the overflow itself.
bool overflows_broken(int64_t pos, int64_t qty) {
    return pos + qty < pos;
}

// Compares with the limits first, so it never overflows.
bool overflows_safe(int64_t pos, int64_t qty) {
    if (qty > 0) {
        return pos > std::numeric_limits<int64_t>::max() - qty;
    }
    return pos < std::numeric_limits<int64_t>::min() - qty;
}

int main() {
    const int64_t max = std::numeric_limits<int64_t>::max();
    const int64_t fills[][2] = {{100, 50}, {100, -50}, {max - 5, 5}, {max - 5, 10}};
    std::cout << std::boolalpha;
    for (const auto& f : fills) {
        std::cout << f[0] << " + " << f[1] << ": broken " << overflows_broken(f[0], f[1])
                  << ", safe " << overflows_safe(f[0], f[1]) << '\n';
    }
    return 0;
}

