#include <cstddef>
#include <iostream>
#include <vector>

struct Order {
    int id;
    double price;
    int qty;
};

int main() {
    const Order incoming[] = {{1, 101.25, 5}, {2, 101.27, 3}, {3, 101.30, 8},
                              {4, 101.24, 2}, {5, 101.31, 1}};
    std::vector<Order> book;
    std::size_t best = 0;  // an index stays valid when the vector moves
    std::size_t capacity = book.capacity();
    for (const Order& o : incoming) {
        book.push_back(o);
        if (book.capacity() != capacity) {
            std::cout << "order " << o.id << ": capacity " << capacity << " -> " << book.capacity()
                      << ", every old reference dangles\n";
            capacity = book.capacity();
        }
        if (o.price > book[best].price) {
            best = book.size() - 1;
        }
    }
    std::cout << "best bid: order " << book[best].id << " at " << book[best].price << '\n';

    std::vector<Order> reserved;
    reserved.reserve(5);
    const Order& first = reserved.emplace_back(incoming[0]);
    int moves = 0;
    for (int i = 1; i < 5; ++i) {
        const std::size_t before = reserved.capacity();
        reserved.push_back(incoming[i]);
        if (reserved.capacity() != before) {
            ++moves;
        }
    }
    std::cout << "with reserve(5): " << moves << " moves, first is still order " << first.id << '\n';
    return 0;
}

