#include <cstddef>
#include <cstdint>
#include <iostream>
#include <vector>

bool under_limit(int pos, std::size_t limit) {
    return pos < limit;  // -Wsign-compare: pos becomes unsigned
}

bool under_limit_safe(int pos, std::size_t limit) {
    return pos < static_cast<std::ptrdiff_t>(limit);
}

int main() {
    std::cout << std::boolalpha;
    const uint32_t order_qty = 100;
    const uint32_t filled = 120;  // two fills crossed in flight
    const auto left = order_qty - filled;
    std::cout << "unsigned left: " << left << ", still working: " << (left > 0) << '\n';
    const int64_t left_signed = int64_t{order_qty} - int64_t{filled};
    std::cout << "signed left: " << left_signed << '\n';

    std::cout << "-3 under 5: " << under_limit(-3, 5) << ", safe: " << under_limit_safe(-3, 5) << '\n';

    const std::vector<double> bids = {101.25, 101.24, 101.23};
    const auto n = static_cast<std::ptrdiff_t>(bids.size());
    std::cout << "size - 5: " << bids.size() - 5 << ", signed: " << n - 5 << '\n';
    for (std::size_t i = bids.size(); i-- > 0;) {
        std::cout << i << ' ' << bids[i] << '\n';
    }
    return 0;
}

