#include <cstddef>
#include <iomanip>
#include <iostream>
#include <vector>

// The size resting on three levels in a row, starting at level i.
template <typename Index>
double depth3(const double* sizes, Index i) {
    return sizes[i] + sizes[i + 1] + sizes[i + 2];
}

// Sums the bids of a book stored as {bid0, ask0, bid1, ask1, ...}.
template <typename Index>
double sum_bids(const double* book, Index levels) {
    double sum = 0.0;
    for (Index i = 0; i < levels; ++i) {
        sum += book[2 * i];
    }
    return sum;
}

int main() {
    const std::vector<double> sizes = {5, 3, 8, 2, 7};
    const std::vector<double> book = {101.25, 101.27, 101.24, 101.28, 101.23, 101.29};
    std::cout << std::fixed << std::setprecision(2);
    std::cout << "depth3 at 1: int " << depth3(sizes.data(), 1) << ", unsigned "
              << depth3(sizes.data(), 1u) << ", size_t " << depth3(sizes.data(), std::size_t{1}) << '\n';
    std::cout << "bids: int " << sum_bids(book.data(), 3) << ", unsigned " << sum_bids(book.data(), 3u)
              << ", size_t " << sum_bids(book.data(), book.size() / 2) << '\n';
    return 0;
}

