#include <cstddef>
#include <iomanip>
#include <iostream>
#include <vector>

int main() {
    std::size_t levels = 0;
    std::cin >> levels;
    std::vector<double> book(2 * levels);
    for (double& px : book) {
        std::cin >> px;
    }
    double total = 0.0;
    std::size_t widest = 0;
    for (std::size_t i = 0; i < levels; ++i) {
        const double spread = book[2 * i + 1] - book[2 * i];
        total += spread;
        if (spread > book[2 * widest + 1] - book[2 * widest]) {
            widest = i;
        }
    }
    std::cout << std::fixed << std::setprecision(4) << "mean spread " << total / levels << '\n';
    std::cout << "widest level " << widest << '\n';
    return 0;
}
